import React, { useState } from "react";
import { db } from "../../firebaseConfig";
import { collection, addDoc } from "firebase/firestore";
import "./CreateExam.css";

const CreateExamPage = () => {
  const [formData, setFormData] = useState({
    subject: "",
    studentClass: "",
    examDate: "",
    startTime: "",
    endTime: "",
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    const { subject, studentClass, examDate, startTime, endTime } = formData;

    // Validate form fields
    if (!subject || !studentClass || !examDate || !startTime || !endTime) {
      alert("Please fill in all fields.");
      return;
    }

    try {
      setLoading(true);

      // Combine date and time for Firestore
      const startDateTime = new Date(`${examDate}T${startTime}`);
      const endDateTime = new Date(`${examDate}T${endTime}`);

      // Add exam to Firestore
      await addDoc(collection(db, "exams"), {
        subject,
        class: studentClass,
        examDate: new Date(examDate),
        startTime: startDateTime.toISOString(),
        endTime: endDateTime.toISOString(),
      });

      alert("Exam created successfully!");
      setFormData({
        subject: "",
        studentClass: "",
        examDate: "",
        startTime: "",
        endTime: "",
      });
    } catch (error) {
      console.error("Error creating exam:", error);
      alert("Failed to create exam. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="create-exam-page">
      <h2>Create a New Exam</h2>
      <form onSubmit={handleSubmit} className="create-exam-form">
        <div className="form-group">
          <label>Subject:</label>
          <input
            type="text"
            name="subject"
            value={formData.subject}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group">
          <label>Class:</label>
          <input
            type="text"
            name="studentClass"
            value={formData.studentClass}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group">
          <label>Exam Date:</label>
          <input
            type="date"
            name="examDate"
            value={formData.examDate}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group">
          <label>Start Time:</label>
          <input
            type="time"
            name="startTime"
            value={formData.startTime}
            onChange={handleChange}
            required
          />
        </div>

        <div className="form-group">
          <label>End Time:</label>
          <input
            type="time"
            name="endTime"
            value={formData.endTime}
            onChange={handleChange}
            required
          />
        </div>

        <button type="submit" className="create-exam-btn" disabled={loading}>
          {loading ? "Creating..." : "Create Exam"}
        </button>
      </form>
    </div>
  );
};

export default CreateExamPage;
